//@target illustrator
// Builds "ACES is shaping futures poster, 11 x 17" as a native Illustrator document in NMSU branding.
// Generated by deslop-marcomm; edit the job's build.py, not this file.
//
// Run: Illustrator > File > Scripts > Other Script... > pick this file.
// Then File > Save As... > Adobe Illustrator (.ai).
//
// Colors are global process swatches in an "NMSU Brand" swatch group, so
// recoloring a swatch recolors everything that uses it, and light fills
// are tints of those swatches. Each box and its text are grouped and named.
//
// A photo slot is a group with a light frame and an X. To fill it, place
// the photo, move it under the frame, delete the X, select the photo and
// the frame, and choose Object > Clipping Mask > Make. A placed image whose
// name starts with "FPO" is a low-resolution stand-in: relink it to the
// final file (Links panel > Relink) before the piece goes out.

// Set to true on a machine that has Gotham (NMSU's primary typeface).
// Otherwise Montserrat is used, which NMSU approves as its substitute.
var PREFER_GOTHAM = false;

var W = 792;
var H = 1224;
var GOTHAM = {"Montserrat-Regular": "Gotham-Book", "Montserrat-Medium": "Gotham-Book", "Montserrat-SemiBold": "Gotham-Medium", "Montserrat-Bold": "Gotham-Bold", "Montserrat-ExtraBold": "Gotham-Black", "Montserrat-Black": "Gotham-Black"};
var SWATCHES = [{"name": "NMSU Aggie Crimson", "rgb": [140, 11, 66]}, {"name": "NMSU White Sands", "rgb": [255, 255, 255]}, {"name": "NMSU Organ Mountain", "rgb": [182, 165, 173]}, {"name": "NMSU Desert Sand", "rgb": [215, 201, 196]}, {"name": "NMSU Azure Sky", "rgb": [0, 157, 184]}, {"name": "NMSU Desert Monsoon", "rgb": [109, 110, 113]}, {"name": "NMSU Sagebrush Mint", "rgb": [108, 195, 188]}, {"name": "NMSU Mesilla Valley Sunset", "rgb": [242, 130, 79]}, {"name": "NMSU Black", "rgb": [35, 31, 32]}];
var LAYERS = [{"name": "Background", "locked": true, "items": [{"kind": "rect", "name": "Page", "x": 0, "y": 0, "w": 792, "h": 1224, "r": 0, "fill": ["NMSU White Sands", 100], "stroke": null, "sw": 0}]}, {"name": "Heading", "locked": false, "items": [{"kind": "text", "name": "Heading 1", "lines": ["THE COLLEGE OF"], "cx": 396.0, "y": 80.1, "font": "Montserrat-Medium", "size": 26, "leads": [32.0], "paint": ["NMSU Azure Sky", 100]}, {"kind": "text", "name": "Heading 2", "lines": ["Agriculture, Consumer,", "and Environmental Sciences"], "cx": 396.0, "y": 130.1, "font": "Montserrat-ExtraBold", "size": 44, "leads": [50.0, 50.0], "paint": ["NMSU Aggie Crimson", 100]}, {"kind": "text", "name": "Heading 3", "lines": ["is shaping futures"], "cx": 396.0, "y": 226.1, "font": "Montserrat-Bold", "size": 34, "leads": [46.0], "paint": ["NMSU Azure Sky", 100]}]}, {"name": "Photos", "locked": false, "items": [{"kind": "group", "name": "Photo 1 (4.92 x 5.28 in)", "items": [{"kind": "rect", "name": "frame", "x": 36.0, "y": 288.0, "w": 354.0, "h": 380.0, "r": 0, "fill": ["NMSU Aggie Crimson", 8], "stroke": null, "sw": 0}, {"kind": "path", "name": "placeholder", "pts": [[36.0, 288.0], [390.0, 668.0]], "closed": false, "fill": null, "stroke": ["NMSU Aggie Crimson", 30], "sw": 1}, {"kind": "path", "name": "placeholder", "pts": [[390.0, 288.0], [36.0, 668.0]], "closed": false, "fill": null, "stroke": ["NMSU Aggie Crimson", 30], "sw": 1}]}, {"kind": "group", "name": "Photo 2 (4.92 x 2.56 in)", "items": [{"kind": "rect", "name": "frame", "x": 402.0, "y": 288.0, "w": 354.0, "h": 184.0, "r": 0, "fill": ["NMSU Aggie Crimson", 8], "stroke": null, "sw": 0}, {"kind": "path", "name": "placeholder", "pts": [[402.0, 288.0], [756.0, 472.0]], "closed": false, "fill": null, "stroke": ["NMSU Aggie Crimson", 30], "sw": 1}, {"kind": "path", "name": "placeholder", "pts": [[756.0, 288.0], [402.0, 472.0]], "closed": false, "fill": null, "stroke": ["NMSU Aggie Crimson", 30], "sw": 1}]}, {"kind": "group", "name": "Photo 3 (2.38 x 2.56 in)", "items": [{"kind": "rect", "name": "frame", "x": 402.0, "y": 484.0, "w": 171.0, "h": 184.0, "r": 0, "fill": ["NMSU Aggie Crimson", 8], "stroke": null, "sw": 0}, {"kind": "path", "name": "placeholder", "pts": [[402.0, 484.0], [573.0, 668.0]], "closed": false, "fill": null, "stroke": ["NMSU Aggie Crimson", 30], "sw": 1}, {"kind": "path", "name": "placeholder", "pts": [[573.0, 484.0], [402.0, 668.0]], "closed": false, "fill": null, "stroke": ["NMSU Aggie Crimson", 30], "sw": 1}]}, {"kind": "group", "name": "Photo 4 (2.38 x 5.28 in)", "items": [{"kind": "rect", "name": "frame", "x": 585.0, "y": 484.0, "w": 171.0, "h": 380.0, "r": 0, "fill": ["NMSU Aggie Crimson", 8], "stroke": null, "sw": 0}, {"kind": "path", "name": "placeholder", "pts": [[585.0, 484.0], [756.0, 864.0]], "closed": false, "fill": null, "stroke": ["NMSU Aggie Crimson", 30], "sw": 1}, {"kind": "path", "name": "placeholder", "pts": [[756.0, 484.0], [585.0, 864.0]], "closed": false, "fill": null, "stroke": ["NMSU Aggie Crimson", 30], "sw": 1}]}, {"kind": "group", "name": "Photo 5 (2.38 x 2.56 in)", "items": [{"kind": "rect", "name": "frame", "x": 36.0, "y": 680.0, "w": 171.0, "h": 184.0, "r": 0, "fill": ["NMSU Aggie Crimson", 8], "stroke": null, "sw": 0}, {"kind": "path", "name": "placeholder", "pts": [[36.0, 680.0], [207.0, 864.0]], "closed": false, "fill": null, "stroke": ["NMSU Aggie Crimson", 30], "sw": 1}, {"kind": "path", "name": "placeholder", "pts": [[207.0, 680.0], [36.0, 864.0]], "closed": false, "fill": null, "stroke": ["NMSU Aggie Crimson", 30], "sw": 1}]}, {"kind": "group", "name": "Photo 6 (4.92 x 2.56 in)", "items": [{"kind": "rect", "name": "frame", "x": 219.0, "y": 680.0, "w": 354.0, "h": 184.0, "r": 0, "fill": ["NMSU Aggie Crimson", 8], "stroke": null, "sw": 0}, {"kind": "path", "name": "placeholder", "pts": [[219.0, 680.0], [573.0, 864.0]], "closed": false, "fill": null, "stroke": ["NMSU Aggie Crimson", 30], "sw": 1}, {"kind": "path", "name": "placeholder", "pts": [[573.0, 680.0], [219.0, 864.0]], "closed": false, "fill": null, "stroke": ["NMSU Aggie Crimson", 30], "sw": 1}]}]}, {"name": "Tagline and logo", "locked": false, "items": [{"kind": "image", "name": "FPO - Tagline", "file": "tagline-student.png", "x": 36, "y": 944.89, "w": 470, "h": 198.23}, {"kind": "logo", "name": "NMSU logo", "file": "nmsu-vertical-setup-crimson.svg", "x": 555.52, "y": 982.0, "w": 200.48, "h": 124}]}];

(function () {
    // Photos and logos are linked from the assets folder next to this script.
    var HERE = new File($.fileName).parent.fsName;
    function asset(name) {
        var f = new File(HERE + "/assets/" + name);
        if (!f.exists) throw new Error("Can't find " + f.fsName + ". Keep the assets folder next to this script.");
        return f;
    }

    var savedCoords = app.coordinateSystem;
    app.coordinateSystem = CoordinateSystem.DOCUMENTCOORDINATESYSTEM;

    var doc = app.documents.add(DocumentColorSpace.RGB, W, H);
    // artboardRect is [left, top, right, bottom] with y growing upward; the
    // layout is written top-down from the artboard's top-left corner.
    var ab = doc.artboards[0].artboardRect;
    function X(x) { return ab[0] + x; }
    function Y(y) { return ab[1] - y; }

    var brand = doc.swatchGroups.add();
    brand.name = "NMSU Brand";
    var spots = {};
    for (var i = 0; i < SWATCHES.length; i++) {
        var s = SWATCHES[i];
        var c = new RGBColor();
        c.red = s.rgb[0]; c.green = s.rgb[1]; c.blue = s.rgb[2];
        var spot = doc.spots.add();
        spot.name = s.name;
        spot.colorType = ColorModel.PROCESS;
        spot.color = c;
        brand.addSpot(spot);
        spots[s.name] = spot;
    }
    function paint(p) {
        if (!p) return null;
        var sc = new SpotColor();
        sc.spot = spots[p[0]];
        sc.tint = p[1];
        return sc;
    }

    var fonts = {}, missing = [];
    function font(ps) {
        if (fonts.hasOwnProperty(ps)) return fonts[ps];
        var names = PREFER_GOTHAM ? [GOTHAM[ps], ps] : [ps];
        for (var i = 0; i < names.length; i++) {
            try { return (fonts[ps] = app.textFonts.getByName(names[i])); } catch (e) {}
        }
        missing.push(ps);
        return (fonts[ps] = null);
    }

    function finish(p, it) {
        p.name = it.name;
        var f = paint(it.fill), s = paint(it.stroke);
        p.filled = !!f;
        if (f) p.fillColor = f;
        p.stroked = !!s;
        if (s) { p.strokeColor = s; p.strokeWidth = it.sw; p.strokeJoin = StrokeJoin.ROUNDENDJOIN; }
        return p;
    }

    function draw(parent, it) {
        var p;
        if (it.kind === "group") {
            var g = parent.groupItems.add();
            g.name = it.name;
            for (var i = 0; i < it.items.length; i++) draw(g, it.items[i]);
        } else if (it.kind === "rect") {
            p = it.r ? parent.pathItems.roundedRectangle(Y(it.y), X(it.x), it.w, it.h, it.r, it.r)
                     : parent.pathItems.rectangle(Y(it.y), X(it.x), it.w, it.h);
            finish(p, it);
        } else if (it.kind === "circle") {
            p = parent.pathItems.ellipse(Y(it.cy - it.r), X(it.cx - it.r), 2 * it.r, 2 * it.r);
            finish(p, it);
        } else if (it.kind === "path") {
            p = parent.pathItems.add();
            var pts = [];
            for (var j = 0; j < it.pts.length; j++) pts.push([X(it.pts[j][0]), Y(it.pts[j][1])]);
            p.setEntirePath(pts);
            p.closed = it.closed;
            finish(p, it);
        } else if (it.kind === "image") {
            // Linked; embed it from the Links panel to make the .ai self-contained.
            p = parent.placedItems.add();
            p.file = asset(it.file);
            p.name = it.name;
            p.width = it.w;
            p.height = it.h;
            p.position = [X(it.x), Y(it.y)];
        } else if (it.kind === "logo") {
            // NMSU's own logo file, imported as vector art and only scaled.
            var lg = parent.groupItems.createFromFile(asset(it.file));
            lg.name = it.name;
            lg.width = it.w;
            lg.height = it.h;
            lg.position = [X(it.x), Y(it.y)];
        } else if (it.kind === "text") {
            var t = parent.textFrames.pointText([X(it.cx), Y(it.y)]);
            t.contents = it.lines.join("\r");
            t.name = it.name;
            var r = t.textRange;
            r.paragraphAttributes.justification = Justification.CENTER;
            var a = r.characterAttributes;
            var f = font(it.font);
            if (f) a.textFont = f;
            a.size = it.size;
            a.autoLeading = false;
            a.leading = it.leads[0];
            a.fillColor = paint(it.paint);
            // Extra space above a line is carried as that line's leading.
            for (var k = 1; k < it.leads.length; k++) {
                t.paragraphs[k].characterAttributes.leading = it.leads[k];
            }
            // Point text is anchored on its first baseline; make sure the
            // centered lines straddle cx however the anchor behaved.
            var gb = t.geometricBounds;
            var dx = X(it.cx) - (gb[0] + gb[2]) / 2;
            if (Math.abs(dx) > 0.25) t.translate(dx, 0);
        }
    }

    // LAYERS runs bottom to top, and layers.add() stacks each new one on top.
    for (var n = 0; n < LAYERS.length; n++) {
        var layer = n === 0 ? doc.layers[0] : doc.layers.add();
        layer.name = LAYERS[n].name;
        for (var m = 0; m < LAYERS[n].items.length; m++) draw(layer, LAYERS[n].items[m]);
        layer.locked = LAYERS[n].locked;
    }

    app.coordinateSystem = savedCoords;
    doc.selection = null;
    app.redraw();
    if (missing.length) {
        alert("Built, but these fonts are not installed:\n  " + missing.join("\n  ") +
              "\n\nInstall Montserrat (brand/fonts/montserrat in deslop-marcomm, or Google " +
              "Fonts), or set PREFER_GOTHAM = true if Gotham is installed, then run again.");
    }
})();
